from django.contrib.auth import get_user_model
from django.db import models

User = get_user_model()


class UserAdminConfig(models.Model):
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    url_name = models.CharField(max_length=100)  # identify the config
    url_full_path = models.TextField()

    def __str__(self):
        return f'{self.url_name}'


class HelpLink(models.Model):
    url_source = models.CharField(max_length=100, db_index=True, unique=True)
    url_help = models.URLField(max_length=400)

    class Meta:
        verbose_name = 'Link para Documentação'
        verbose_name_plural = 'Links de Documentação'

    def __str__(self):
        return self.url_source
